"use strict";(globalThis.webpackChunkistqb_quiz=globalThis.webpackChunkistqb_quiz||[]).push([[972],{972(e){e.exports=JSON.parse('[{"id":250,"chapter":1,"topic":"Fundamentos del Testing","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit un objectif de test valide\xa0?","options":["A) D\xe9montrer qu\'il n\'y a aucun d\xe9faut non corrig\xe9 dans le syst\xe8me test\xe9","B) D\xe9montrer qu\'il n\'y aura aucune panne apr\xe8s la mise en \u0153uvre du syst\xe8me en production","C) R\xe9duire le niveau de risque de l\'objet de test et renforcer la confiance dans le niveau de qualit\xe9 D) V\xe9rifier qu\'il n\'existe aucune combinaison d\'entr\xe9es non test\xe9e"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#1, LO\xa0: FL-1.1.1). Justification\xa0:\xa0R\xe9duire le niveau de risque de l\'objet de test et renforcer la confiance dans le niveau de qualit\xe9. D) V\xe9rifier qu\'il n\'existe aucune combinaison d\'entr\xe9es non test\xe9e.","source":"Official Sample Exam A Q#1"},{"id":251,"chapter":1,"topic":"Fundamentos del Testing","question":"Lequel des \xe9l\xe9ments suivants montre un exemple d\u2019activit\xe9s de test qui contribuent au succ\xe8s\xa0?","options":["A) L\'implication des testeurs lors de diverses activit\xe9s du cycle de vie du d\xe9veloppement logiciel (SDLC) aidera \xe0 d\xe9tecter les d\xe9fauts dans les produits de travail.","B) Les testeurs essaient de ne pas d\xe9ranger les d\xe9veloppeurs pendant la programmation, afin que les d\xe9veloppeurs \xe9crivent un meilleur code","C) Les testeurs collaborant avec les utilisateurs finaux contribuent \xe0 am\xe9liorer la qualit\xe9 des rapports de d\xe9fauts lors des tests d\'int\xe9gration de composants et des tests du syst\xe8me."],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#2, LO : FL-1.2.1). Justification\xa0:\xa0l\'implication des testeurs lors de diverses activit\xe9s du cycle de vie du d\xe9veloppement logiciel (SDLC) aidera \xe0 d\xe9tecter les d\xe9fauts dans les produits de travail.","source":"Official Sample Exam A Q#2"},{"id":252,"chapter":1,"topic":"Fundamentos del Testing","question":"Vous avez \xe9t\xe9 affect\xe9 en tant que testeur \xe0 une \xe9quipe qui produit progressivement un nouveau syst\xe8me. Vous avez remarqu\xe9 qu\'aucune modification n\'a \xe9t\xe9 apport\xe9e aux cas de test de r\xe9gression existants depuis plusieurs it\xe9rations et qu\'aucun nouveau d\xe9faut de r\xe9gression n\'a \xe9t\xe9 identifi\xe9. Votre manager est content, mais vous ne l\'\xeates pas. Quel principe de preuve explique votre scepticisme ?","options":["A) Les tests s\'usent","B) Erreur d\'absence de d\xe9fauts","C) Les d\xe9fauts sont regroup\xe9s","D) Des tests exhaustifs sont impossibles"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#3, LO : FL-1.3.1). Justification\xa0:\xa0les preuves s\'usent","source":"Official Sample Exam A Q#3"},{"id":253,"chapter":1,"topic":"Fundamentos del Testing","question":"Vous travaillez dans une \xe9quipe qui d\xe9veloppe une application mobile pour commander de la nourriture. Dans l\'it\xe9ration actuelle, l\'\xe9quipe a d\xe9cid\xe9 d\'impl\xe9menter une fonctionnalit\xe9 de paiement. Laquelle des activit\xe9s suivantes fait partie de l\u2019analyse des tests\xa0?","options":["A) Estimez que le test de l\'int\xe9gration avec le service de paiement prendra 8 jours-personnes","B) D\xe9cidez que l\'\xe9quipe doit tester s\'il est possible de partager le paiement de mani\xe8re appropri\xe9e entre de nombreux utilisateurs.","C) Utiliser l\'analyse des valeurs limites (BVA) pour d\xe9river des donn\xe9es de test pour les cas de test qui v\xe9rifient le traitement correct des paiements pour le montant minimum autoris\xe9 \xe0 \xeatre pay\xe9.","D) Analyser l\'\xe9cart entre le r\xe9sultat r\xe9el et le r\xe9sultat attendu apr\xe8s avoir ex\xe9cut\xe9 un sc\xe9nario de test qui v\xe9rifie le processus de paiement par carte de cr\xe9dit et signaler un d\xe9faut"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#4, LO : FL-1.4.1). Justification\xa0:\xa0D\xe9cidez que l\'\xe9quipe doit tester s\'il est possible de partager le paiement de mani\xe8re appropri\xe9e entre de nombreux utilisateurs.","source":"Official Sample Exam A Q#4"},{"id":254,"chapter":1,"topic":"Fundamentos del Testing","question":"Parmi les facteurs suivants, lesquels ont une influence SIGNIFICATIVE sur l\'approche de test\xa0? Yo. Le SDLC ii. Le nombre de d\xe9fauts d\xe9tect\xe9s dans les projets pr\xe9c\xe9dents iii. Les risques li\xe9s aux produits identifi\xe9s iv. Nouvelles exigences r\xe9glementaires exigeant des tests formels en bo\xeete blanche v. Mise en place de l\'environnement de test","options":["A) i, ii ont une influence significative","B) i, iii, iv ont une influence significative","C) ii, iv, v ont une influence significative","D) iii, v ont une influence significative"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#5, LO : FL-1.4.2). Justification\xa0:\xa0i, iii, iv ont une influence significative","source":"Official Sample Exam A Q#5"},{"id":255,"chapter":1,"topic":"Fundamentos del Testing","question":"Parmi les t\xe2ches suivantes, lesquelles appartiennent PRINCIPALEMENT \xe0 un r\xf4le de test\xa0?","options":["A) Mettre en place des environnements de test","B) Maintenir le backlog produit","C) Concevoir des solutions aux nouvelles exigences","D) Cr\xe9er le plan de test","E) Analyser la base de donn\xe9es factuelles"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#6, LO : FL-1.4.5). Justification\xa0: Mettre en place des environnements de test","source":"Official Sample Exam A Q#6"},{"id":256,"chapter":1,"topic":"Fundamentos del Testing","question":"Parmi les comp\xe9tences suivantes (i-v), lesquelles sont les PLUS importantes pour un testeur\xa0? Yo. Avoir une connaissance du domaine ii. Cr\xe9er une vision du produit iii. \xcatre un bon joueur d\'\xe9quipe iv. Planifier et organiser le travail de l\'\xe9quipe v. Pens\xe9e critique","options":["A) ii et iv sont importants","B) i, iii et v sont importants","C) i, ii et v sont importants","D) iii et iv sont importants"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#7, LO : FL-1.5.1). Justification\xa0:\xa0i, iii et v sont importants","source":"Official Sample Exam A Q#7"},{"id":257,"chapter":1,"topic":"Fundamentos del Testing","question":"Comment l\u2019approche globale de l\u2019\xe9quipe est-elle pr\xe9sente dans les interactions entre testeurs et repr\xe9sentants m\xe9tiers ?","options":["A) Les repr\xe9sentants de l\'entreprise d\xe9cident des approches d\'automatisation des tests","B) Les testeurs aident les repr\xe9sentants de l\'entreprise \xe0 d\xe9finir une strat\xe9gie de test","C) Les repr\xe9sentants des entreprises ne font pas partie de l\'attention de toute l\'\xe9quipe","D) Les testeurs aident les repr\xe9sentants commerciaux \xe0 cr\xe9er des tests d\'acceptation appropri\xe9s"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#8, LO : FL-1.5.2). Justification\xa0: les testeurs aident les repr\xe9sentants des entreprises \xe0 cr\xe9er des tests d\'acceptation appropri\xe9s","source":"Official Sample Exam A Q#8"},{"id":258,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Consid\xe9rez la r\xe8gle suivante : \xab\xa0\xe0 chaque activit\xe9 SDLC, il existe une activit\xe9 de test correspondante\xa0\xbb. Dans quels mod\xe8les SDLC cette r\xe8gle s\u2019applique-t-elle\xa0?","options":["A) Uniquement dans les mod\xe8les de d\xe9veloppement s\xe9quentiel","B) Uniquement dans les mod\xe8les de d\xe9veloppement it\xe9ratifs","C) Uniquement dans les mod\xe8les de d\xe9veloppement it\xe9ratifs et incr\xe9mentaux","D) Dans les mod\xe8les de d\xe9veloppement s\xe9quentiel, incr\xe9mental et it\xe9ratif"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#9, LO : FL-2.1.2). Justification\xa0: Dans les mod\xe8les de d\xe9veloppement s\xe9quentiel, incr\xe9mentiel et it\xe9ratif","source":"Official Sample Exam A Q#9"},{"id":259,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX l\u2019approche de d\xe9veloppement pilot\xe9 par les tests d\u2019acceptation (ATDD)\xa0?","options":["A) Dans ATDD, les crit\xe8res d\'acceptation sont g\xe9n\xe9ralement cr\xe9\xe9s en fonction du format donn\xe9/quand/alors.","B) Dans ATDD, les cas de tests sont principalement cr\xe9\xe9s dans les tests de composants et sont orient\xe9s code","C) Dans ATDD, les tests sont cr\xe9\xe9s sur la base de crit\xe8res d\'acceptation pour guider le d\xe9veloppement des logiciels associ\xe9s","D) Dans ATDD, les tests sont bas\xe9s sur le comportement souhait\xe9 du logiciel, ce qui facilite la compr\xe9hension des membres de l\'\xe9quipe"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#10, LO : FL-2.1.3). Justification\xa0: Dans ATDD, les tests sont cr\xe9\xe9s sur la base de crit\xe8res d\'acceptation pour guider le d\xe9veloppement de logiciels associ\xe9s.","source":"Official Sample Exam A Q#10"},{"id":260,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Lequel des \xe9nonc\xe9s suivants n\u2019est PAS un exemple de l\u2019approche Shift-Gauche\xa0?","options":["A) Examiner les exigences des utilisateurs avant qu\'elles ne soient formellement accept\xe9es par les parties prenantes","B) \xc9crire un test de composant avant d\'\xe9crire le code correspondant","C) Ex\xe9cuter un test d\'efficacit\xe9 des performances pour un composant pendant les tests de composants","D) \xc9crivez un script de test avant de configurer le processus de gestion de la configuration"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#11, LO : FL-2.1.5). Justification\xa0: \xc9crivez un script de test avant de configurer le processus de gestion de la configuration.","source":"Official Sample Exam A Q#11"},{"id":261,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Lequel des arguments suivants utiliseriez-vous pour convaincre votre manager d\u2019organiser des r\xe9trospectives\xa0?","options":["A) Les r\xe9trospectives sont tr\xe8s populaires de nos jours et les clients appr\xe9cieraient que nous les ajoutions \xe0 nos processus","B) L\'organisation de r\xe9trospectives permettra \xe0 l\'organisation d\'\xe9conomiser de l\'argent, car sans elles, les repr\xe9sentants des utilisateurs finaux ne fournissent pas de commentaires imm\xe9diats sur le produit.","C) Les faiblesses des processus identifi\xe9es lors de la r\xe9trospective peuvent \xeatre analys\xe9es et servir de liste de t\xe2ches pour le programme d\'am\xe9lioration continue des processus de l\'organisation.","D) Les r\xe9trospectives englobent cinq valeurs, dont le courage et le respect, qui sont essentielles au maintien de l\'am\xe9lioration continue de l\'organisation."],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#12, LO : FL-2.1.6). Justification\xa0: Les faiblesses des processus identifi\xe9es au cours de la r\xe9trospective peuvent \xeatre analys\xe9es et servir de liste de t\xe2ches pour le programme d\'am\xe9lioration continue des processus de l\'organisation.","source":"Official Sample Exam A Q#12"},{"id":262,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Quels types de d\xe9fauts (1-4) correspondent le MIEUX \xe0 quels niveaux de test (A-D)\xa0? 1. D\xe9faillances dans le comportement du syst\xe8me en s\'\xe9cartant des besoins professionnels de l\'utilisateur 2. D\xe9faillances dans la communication entre les composants 3. D\xe9faillances dans la logique du code 4. D\xe9faillances dues \xe0 des r\xe8gles m\xe9tier mal mises en \u0153uvre A. Tests de composants B. Tests d\'int\xe9gration de composants C. Tests du syst\xe8me D. Tests d\'acceptation","options":["A)1D, 2B, 3A, 4C","B)1D, 2B, 3C, 4A","C)1B, 2A, 3D, 4C","D) 1C, 2B, 3A, 4D"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#13, LO : FL-2.2.1). Justification\xa0: 1D, 2B, 3A, 4C","source":"Official Sample Exam A Q#13"},{"id":263,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Vous testez une user story avec trois crit\xe8res d\u2019acceptation : AC1, AC2 et AC3. AC1 est couvert par le sc\xe9nario de test TC1, AC2 par TC2 et AC3 par TC3. L\'historique des tests comporte trois s\xe9ries de tests sur trois versions cons\xe9cutives du logiciel, comme suit\xa0: Ex\xe9cution 1 Ex\xe9cution 2 Ex\xe9cution 3 TC1 (1) \xc9chec (4) R\xe9ussite (7) R\xe9ussite TC2 (2) R\xe9ussite (5) \xc9chec (8) R\xe9ussite TC3 (3) \xc9chec (6) \xc9chec (9) R\xe9ussite Les tests sont r\xe9p\xe9t\xe9s une fois que vous \xeates inform\xe9 que tous les d\xe9fauts trouv\xe9s lors de la s\xe9rie de tests sont corrig\xe9s et qu\'une nouvelle version du logiciel est disponible. Parmi les tests ci-dessus, lesquels sont ex\xe9cut\xe9s en tant que tests de r\xe9gression\xa0?","options":["A) Seulement 4, 7, 8, 9","B) Seulement 5, 7","C) Seulement 4, 6, 8, 9","D) Seulement 5, 6"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#14, LO : FL-2.2.3). Justification\xa0: seulement 5, 7","source":"Official Sample Exam A Q#14"},{"id":264,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Lequel des \xe9l\xe9ments suivants ne repr\xe9sente PAS un avantage des tests statiques\xa0?","options":["A) Avoir une gestion des d\xe9fauts moins co\xfbteuse en raison de la facilit\xe9 de d\xe9tection des d\xe9fauts plus tard dans le SDLC","B) La r\xe9paration des d\xe9fauts d\xe9tect\xe9s lors des tests statiques est g\xe9n\xe9ralement beaucoup moins co\xfbteuse que la r\xe9paration des d\xe9fauts d\xe9tect\xe9s lors des tests dynamiques","C) Rechercher des d\xe9fauts de codage qui n\'auraient peut-\xeatre pas \xe9t\xe9 d\xe9tect\xe9s en effectuant uniquement des tests dynamiques","D) D\xe9tecter les lacunes et les incoh\xe9rences dans les exigences"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#15, LO : FL-3.1.2). Justification\xa0: Avoir une gestion des d\xe9fauts moins co\xfbteuse en raison de la facilit\xe9 de d\xe9tection des d\xe9fauts plus tard dans le SDLC","source":"Official Sample Exam A Q#15"},{"id":265,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Lequel des \xe9l\xe9ments suivants constitue un avantage d\u2019un retour d\u2019information pr\xe9coce et fr\xe9quent\xa0?","options":["A) Am\xe9liorer le processus de test pour les projets futurs","B) Force les clients \xe0 prioriser leurs exigences en fonction des risques convenus","C) Fournit une mesure de la qualit\xe9 des changements","D) Aide \xe0 \xe9viter les malentendus dans les exigences"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#16, LO : FL-3.2.1). Justification\xa0: Aide \xe0 \xe9viter les malentendus concernant les exigences","source":"Official Sample Exam A Q#16"},{"id":266,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Les \xe9valuations utilis\xe9es dans votre organisation ont les attributs suivants\xa0: \u2022 Il y a un r\xf4le de scribe. \u2022 L\'objectif principal est d\'\xe9valuer la qualit\xe9. \u2022 La r\xe9union est dirig\xe9e par l\'auteur du produit du travail. \u2022 Il y a une pr\xe9paration individuelle. \u2022 Un rapport d\'\xe9valuation est produit. Lequel des types d\'\xe9valuation suivants est le PLUS susceptible d\'\xeatre utilis\xe9\xa0?","options":["A) Examen informel","B) Proc\xe9dure pas \xe0 pas","C) Examen technique","D) Contr\xf4le"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#17, LO : FL-3.2.4). Justification\xa0: Proc\xe9dure pas \xe0 pas","source":"Official Sample Exam A Q#17"},{"id":267,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Laquelle de ces affirmations ne contribue PAS \xe0 la r\xe9ussite des \xe9valuations\xa0?","options":["A) Les participants doivent pr\xe9voir suffisamment de temps pour l\u2019examen","B) Divisez les gros produits de travail en petites parties afin que l\'effort requis soit moins intense","C) Les participants doivent \xe9viter les comportements pouvant indiquer de l\'ennui, de l\'exasp\xe9ration ou de l\'hostilit\xe9 envers les autres participants.","D) Les d\xe9faillances constat\xe9es doivent \xeatre reconnues, appr\xe9ci\xe9es et trait\xe9es objectivement"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#18, LO : FL-3.2.5). Justification\xa0:\xa0les d\xe9faillances constat\xe9es doivent \xeatre reconnues, appr\xe9ci\xe9es et trait\xe9es de mani\xe8re objective","source":"Official Sample Exam A Q#18"},{"id":268,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Lequel des \xe9l\xe9ments suivants est une caract\xe9ristique des techniques de test bas\xe9es sur l\u2019exp\xe9rience\xa0?","options":["A) Les cas de test sont cr\xe9\xe9s sur la base d\'informations de conception d\xe9taill\xe9es","B) Les \xe9l\xe9ments test\xe9s dans la section du code d\'interface sont utilis\xe9s pour mesurer la couverture","C) Les techniques de test d\xe9pendent en grande partie de la connaissance du logiciel et du domaine m\xe9tier du testeur.","D) Les cas de test sont utilis\xe9s pour identifier les \xe9carts par rapport aux exigences"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#19, LO : FL-4.1.1). Justification\xa0: Les techniques de test d\xe9pendent en grande partie de la connaissance du logiciel et du domaine m\xe9tier par le testeur.","source":"Official Sample Exam A Q#19"},{"id":269,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Vous testez un formulaire de recherche d\'appartement simplifi\xe9 qui ne comporte que deux crit\xe8res de recherche : \u2022 \xe9tage (avec trois options possibles : rez-de-chauss\xe9e ; premier \xe9tage ; deuxi\xe8me \xe9tage ou sup\xe9rieur) \u2022 type de jardin (avec trois options possibles : pas de jardin ; petit jardin ; grand jardin) Tous les appartements du rez-de-chauss\xe9e ont un jardin, les appartements des \xe9tages n\'en ont pas. Le formulaire dispose d\'un m\xe9canisme de validation int\xe9gr\xe9 qui ne vous permettra pas d\'utiliser des crit\xe8res de recherche qui enfreignent cette r\xe8gle. Chaque test comporte deux valeurs d\'entr\xe9e\xa0: le type de sol et le type de jardin. Vous souhaitez appliquer un cloisonnement d\'\xe9quivalence (EP) pour couvrir chaque \xe9tage et chaque type de jardin dans vos tests. Quel est le nombre minimum de cas de test pour obtenir une couverture EP \xe0 100\xa0% pour les partitions valides\xa0?","options":["A)3","B)4","C)5","D)6"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#20, LO : FL-4.2.1). Justification : 4","source":"Official Sample Exam A Q#20"},{"id":270,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Vous testez un syst\xe8me qui calcule la note finale du cours pour un \xe9tudiant donn\xe9. La note finale est attribu\xe9e en fonction du r\xe9sultat final, selon les r\xe8gles suivantes : \u2022 0 \u2013 50 points : \xe9chou\xe9 \u2022 51 \u2013 60 points : suffisant \u2022 61 \u2013 70 points : satisfaisant \u2022 71 \u2013 80 points : bon \u2022 81 \u2013 90 points : tr\xe8s bien \u2022 91 \u2013 100 points : excellent Vous avez pr\xe9par\xe9 l\'ensemble de cas de test suivant : R\xe9sultat final Note finale TC1 91 excellent TC2 50 \xe9chou\xe9 TC3 81 tr\xe8s bien TC4 60 suffisant TC5 70 satisfaisant TC6 80 bon Quelle est la couverture de l\'analyse des valeurs limites (BVA) \xe0 2 valeurs pour le r\xe9sultat final obtenu avec les cas de test existants\xa0?","options":["A) 50\xa0%","B) 60\xa0%","C) 33,3%","D) 100\xa0%"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#21, LO : FL-4.2.2). Justification : 50%","source":"Official Sample Exam A Q#21"},{"id":271,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Votre magasin de location de v\xe9los \xe0 la journ\xe9e pr\xe9f\xe9r\xe9 vient de pr\xe9senter un nouveau syst\xe8me de gestion de la relation client (CRM) et vous a demand\xe9, en tant que l\'un de ses membres les plus fid\xe8les, de l\'essayer. Les fonctionnalit\xe9s mises en place sont les suivantes : \u2022 Tout le monde peut louer un v\xe9lo, mais les membres b\xe9n\xe9ficient d\'une r\xe9duction de 20 %. \u2022 Toutefois, si la date limite de retour est d\xe9pass\xe9e, la r\xe9duction n\'est plus disponible. \u2022 Apr\xe8s 15 locations, les membres re\xe7oivent un cadeau : un t-shirt. La table de d\xe9cision d\xe9crivant les fonctionnalit\xe9s mises en \u0153uvre ressemble \xe0 ceci : Conditions R1 R2 R3 R4 R5 R6 R7 R8 \xcatre membre T T T T F F F F D\xe9lai non respect\xe9 T F T F T F F T 15\xe8me location F F T T F F T T Actions Remise de 20 % X","options":["A)R4","B)R2","C)R6","D) R8"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#22, LO : FL-4.2.3). Justification : R8","source":"Official Sample Exam A Q#22"},{"id":272,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Testez un syst\xe8me dont le cycle de vie est mod\xe9lis\xe9 par le diagramme de transition d\'\xe9tat pr\xe9sent\xe9 ci-dessous. Le syst\xe8me d\xe9marre \xe0 l\'\xe9tat INIT et termine son fonctionnement \xe0 l\'\xe9tat OFF. Quel est le nombre MINIMUM de cas de test pour obtenir une couverture de transition valide\xa0?","options":["A)4","B)2","C)7","D)3"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#23, LO : FL-4.2.4). Justification : 3","source":"Official Sample Exam A Q#23"},{"id":273,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Leur suite de tests a atteint une couverture de phrases \xe0 100\xa0%. Quelle est la cons\xe9quence de ce fait ?","options":["A) Chaque instruction du code contenant un d\xe9faut a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois","B) Toute suite de tests contenant plus de cas de test que votre suite de tests atteindra \xe9galement une couverture des d\xe9clarations \xe0 100 %","C) Chaque route du code a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois","D) Chaque combinaison de valeurs d\'entr\xe9e a \xe9t\xe9 test\xe9e au moins une fois"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#24, LO : FL-4.3.1). Justification\xa0: chaque instruction du code contenant un d\xe9faut a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois.","source":"Official Sample Exam A Q#24"},{"id":274,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Laquelle des affirmations suivantes n\u2019est PAS vraie pour les tests en bo\xeete blanche\xa0?","options":["A) Lors des tests en bo\xeete blanche, l\'ensemble de la mise en \u0153uvre du logiciel est pris en compte","B) Les m\xe9triques de couverture en bo\xeete blanche peuvent aider \xe0 identifier des tests suppl\xe9mentaires pour augmenter la couverture du code","C) Les techniques de test en bo\xeete blanche peuvent \xeatre utilis\xe9es dans les tests statiques","D) Les tests en bo\xeete blanche peuvent aider \xe0 identifier les lacunes dans la mise en \u0153uvre des exigences"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#25, LO : FL-4.3.3). Justification\xa0: les tests en bo\xeete blanche peuvent aider \xe0 identifier les lacunes dans la mise en \u0153uvre des exigences.","source":"Official Sample Exam A Q#25"},{"id":275,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit le MIEUX le concept derri\xe8re la supposition d\u2019erreur\xa0?","options":["A) La pr\xe9diction des bogues implique d\'utiliser vos connaissances et votre exp\xe9rience sur les d\xe9fauts trouv\xe9s dans le pass\xe9 et les erreurs typiques commises par les d\xe9veloppeurs.","B) La pr\xe9diction des bugs implique d\'utiliser votre exp\xe9rience de d\xe9veloppement personnel et les erreurs que vous avez commises en tant que d\xe9veloppeur","C) La pr\xe9diction des erreurs vous oblige \xe0 imaginer que vous \xeates l\'utilisateur de l\'objet de test et \xe0 deviner les erreurs que l\'utilisateur pourrait commettre en interagissant avec lui.","D) La pr\xe9diction des bogues vous oblige \xe0 dupliquer rapidement la t\xe2che de d\xe9veloppement pour identifier le type de bogues qu\'un d\xe9veloppeur pourrait cr\xe9er."],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#26, LO : FL-4.4.1). Justification\xa0:\xa0La pr\xe9diction des bogues implique d\'utiliser vos connaissances et votre exp\xe9rience sur les d\xe9fauts d\xe9tect\xe9s dans le pass\xe9 et les erreurs typiques commises par les d\xe9veloppeurs.","source":"Official Sample Exam A Q#26"},{"id":276,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"A commenc\xe9 tardivement mais poss\xe8de une connaissance tr\xe8s d\xe9taill\xe9e du domaine et de bonnes comp\xe9tences analytiques. La liste compl\xe8te des exigences n\'a pas encore \xe9t\xe9 partag\xe9e avec l\'\xe9quipe, mais la direction demande que certains r\xe9sultats de tests soient soumis. Quelle technique de test convient le mieux \xe0 cette situation\xa0?","options":["A) Tests bas\xe9s sur des listes de contr\xf4le","B) Pr\xe9diction des erreurs","C) Tests exploratoires","D) Tests de branche"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#27, LO : FL-4.4.2). Justification\xa0: tests exploratoires","source":"Official Sample Exam A Q#27"},{"id":277,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit le MIEUX comment les crit\xe8res d\u2019acceptation peuvent \xeatre document\xe9s\xa0?","options":["A) R\xe9aliser des r\xe9trospectives pour d\xe9terminer les besoins r\xe9els des parties prenantes concernant une user story donn\xe9e","B) Utiliser le format donn\xe9/quand/alors pour d\xe9crire un exemple de condition de test li\xe9e \xe0 une user story donn\xe9e","C) Utiliser la communication verbale pour r\xe9duire le risque que d\'autres personnes comprennent mal les crit\xe8res d\'acceptation","D) Documenter les risques li\xe9s \xe0 une user story donn\xe9e dans un plan de test pour faciliter les tests bas\xe9s sur les risques d\'une user story donn\xe9e"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#28, LO : FL-4.5.2). Justification\xa0: Utiliser le format donn\xe9/quand/alors pour d\xe9crire un exemple de condition de test li\xe9e \xe0 une user story donn\xe9e","source":"Official Sample Exam A Q#28"},{"id":278,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Consid\xe9rez l\'histoire d\'utilisateur suivante\xa0: En tant qu\'\xe9diteur, je souhaite v\xe9rifier le contenu avant sa publication pour m\'assurer que la grammaire est correcte et ses crit\xe8res d\'acceptation\xa0: \u2022 L\'utilisateur peut se connecter au syst\xe8me de gestion de contenu avec le r\xf4le d\'\xab \xc9diteur \xbb \u2022 L\'\xe9diteur peut afficher les pages de contenu existantes \u2022 L\'\xe9diteur peut modifier le contenu de la page \u2022 L\'\xe9diteur peut ajouter des commentaires de balisage \u2022 L\'\xe9diteur peut enregistrer les modifications \u2022 L\'\xe9diteur peut r\xe9affecter le r\xf4le de \xab propri\xe9taire de contenu \xbb pour effectuer des mises \xe0 jour. Lequel des \xe9l\xe9ments suivants est le MEILLEUR exemple de test ATDD pour cela histoire d\'utilisateur ?","options":["A) Testez si l\'\xe9diteur peut enregistrer le document apr\xe8s avoir modifi\xe9 le contenu de la page","B) Testez si le propri\xe9taire du contenu peut se connecter et effectuer des mises \xe0 jour du contenu","C) Testez si l\'\xe9diteur peut planifier la publication du contenu \xe9dit\xe9","D) Testez si l\'\xe9diteur peut se r\xe9affecter \xe0 un autre \xe9diteur pour effectuer des mises \xe0 jour"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#29, LO : FL-4.5.3). Justification\xa0:\xa0tester si l\'\xe9diteur peut enregistrer le document apr\xe8s avoir modifi\xe9 le contenu de la page","source":"Official Sample Exam A Q#29"},{"id":279,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Parmi les DEUX crit\xe8res suivants, lesquels constituent les crit\xe8res de sortie pour tester un syst\xe8me\xa0?","options":["A) Pr\xe9paration de l\'environnement de test","B) La possibilit\xe9 de se connecter \xe0 l\'objet de test par le testeur","C) La densit\xe9 de d\xe9fauts estim\xe9e est atteinte","D) Les exigences sont traduites au format donn\xe9/quand/alors","E) Les tests de r\xe9gression sont automatis\xe9s"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#31, LO : FL-5.1.3). Justification\xa0:\xa0la densit\xe9 de d\xe9fauts estim\xe9e est atteinte","source":"Official Sample Exam A Q#31"},{"id":280,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Son \xe9quipe utilise la technique d\'estimation en trois points pour estimer l\'effort de test d\'une nouvelle fonctionnalit\xe9 \xe0 haut risque. Les estimations suivantes ont \xe9t\xe9 faites : \u2022 Estimation la plus optimiste : 2 heures-personnes \u2022 Estimation la plus probable : 11 heures-personnes \u2022 Estimation la plus pessimiste : 14 heures-personnes Quelle est l\'estimation finale ?","options":["A) 9 heures-personnes","B) 14 heures-personnes","C) 11 heures-personnes","D) 10 heures-personnes"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#32, LO : FL-5.1.4). Justification\xa0: 10\xa0heures-personnes","source":"Official Sample Exam A Q#32"},{"id":281,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Elle teste une application mobile qui permet aux utilisateurs de trouver un restaurant \xe0 proximit\xe9 en fonction du type de nourriture qu\'ils souhaitent manger. Consid\xe9rez la liste suivante de cas de test, de priorit\xe9s (c\'est-\xe0-dire qu\'un nombre inf\xe9rieur signifie une priorit\xe9 plus \xe9lev\xe9e) et de d\xe9pendances\xa0: Num\xe9ro de cas de test Condition de test couverte Priorit\xe9 D\xe9pendance logique TC 001 S\xe9lectionner le type de nourriture 3 aucun TC 002 S\xe9lectionner le restaurant 2 TC 001 TC 003 Obtenir un itin\xe9raire 1 TC 002 TC 004 Appeler le restaurant 2 TC 002 TC 005 Faire une r\xe9servation 3 TC 002 Lequel des \xe9l\xe9ments suivants les cas de test doivent \xeatre ex\xe9cut\xe9s en troisi\xe8me lieu\xa0?","options":["A) TC 003","B) TC 005","C) TC 002","D) TC 001"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#33, LO : FL-5.1.5). Justification : TC 003","source":"Official Sample Exam A Q#33"},{"id":282,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Consid\xe9rez les cat\xe9gories de tests suivantes (1-4) et les quadrants de tests agiles (A-D)\xa0: 1. Tests d\'utilisabilit\xe9 2. Tests de composants 3. Tests fonctionnels 4. Tests de fiabilit\xe9 A. Quadrant de tests agiles Q1\xa0: orient\xe9 technologie, soutenant l\'\xe9quipe de d\xe9veloppement B. Quadrant de tests agiles Q2\xa0: orient\xe9 commercial, soutenant l\'\xe9quipe de d\xe9veloppement C. Quadrant de tests agiles Q3\xa0: orient\xe9 commercial, critique produit D. Quadrant de tests agiles Q4\xa0: Orient\xe9 technologie, critique produit Comment les cat\xe9gories de tests suivantes correspondent-elles aux quadrants des tests agiles\xa0?","options":["A) 1C, 2A, 3B, 4D","B)1D, 2A, 3C, 4B","C) 1C, 2B, 3D, 4A","D)1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#34, LO : FL-5.1.7). Justification\xa0: 1C, 2A, 3B, 4D","source":"Official Sample Exam A Q#34"},{"id":283,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Lors d\'une analyse des risques, le risque suivant a \xe9t\xe9 identifi\xe9 et \xe9valu\xe9 : \u2022 Risque : le temps de r\xe9ponse est trop long pour g\xe9n\xe9rer un rapport \u2022 Probabilit\xe9 du risque : moyenne ; impact du risque : \xe9lev\xe9 \u2022 R\xe9ponse au risque : o Une \xe9quipe de test ind\xe9pendante effectue des tests d\'efficacit\xe9 des performances pendant les tests du syst\xe8me o Un \xe9chantillon s\xe9lectionn\xe9 d\'utilisateurs finaux effectue des tests alpha et b\xeata avant la sortie. Quelle action proposez-vous de prendre en r\xe9ponse \xe0 ce risque analys\xe9 ?","options":["A) Acceptation du risque","B) Plan d\'urgence","C) Att\xe9nuation des risques","D) Transfert des risques"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#35, LO : FL-5.2.4). Justification\xa0:\xa0Att\xe9nuation des risques","source":"Official Sample Exam A Q#35"},{"id":284,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Quel produit de travail une \xe9quipe agile peut-elle utiliser pour afficher la quantit\xe9 de travail effectu\xe9e et la quantit\xe9 totale de travail restant pour une it\xe9ration donn\xe9e\xa0?","options":["A) Crit\xe8res d\'acceptation","B) Rapport de d\xe9faut","C) Rapport de fin de test","D) Graphique d\'avancement"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#36, LO : FL-5.3.3). Justification\xa0: diagramme d\'avancement","source":"Official Sample Exam A Q#36"},{"id":285,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Vous devez mettre \xe0 jour l\'un des scripts de test automatis\xe9s pour l\'aligner sur une nouvelle exigence. Quel processus indique que vous devez cr\xe9er une nouvelle version du script de test dans le r\xe9f\xe9rentiel de test\xa0?","options":["A) Gestion de la tra\xe7abilit\xe9","B) Essais d\'entretien","C) Gestion des configurations","D) Ing\xe9nierie des exigences"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#37, LO : FL-5.4.1). Justification\xa0:\xa0gestion de la configuration","source":"Official Sample Exam A Q#37"},{"id":286,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Re\xe7u le rapport de d\xe9faut suivant des d\xe9veloppeurs indiquant que l\'anomalie d\xe9crite dans ce rapport de test n\'est pas reproductible. L\'application se bloque 03 mai 2022 \u2013 John Doe \u2013 L\'application rejet\xe9e se bloque apr\xe8s avoir entr\xe9 \xab Test d\'entr\xe9e : $\xe4 \xbb dans le champ Nom de l\'\xe9cran de cr\xe9ation d\'un nouvel utilisateur. J\'ai essay\xe9 de me d\xe9connecter, de me connecter avec le compte test_admin01, m\xeame probl\xe8me. Essay\xe9 avec d\'autres comptes d\'administrateur de test, m\xeame probl\xe8me. Aucun message d\'erreur re\xe7u\xa0; Le journal (voir ci-joint) contient une notification d\'erreur fatale. Sur la base du sc\xe9nario de test TC-1305, l\'application doit accepter l\'entr\xe9e fournie et cr\xe9er l\'utilisateur. Veuillez corriger avec une priorit\xe9 \xe9lev\xe9e, cette fonctionnalit\xe9 est li\xe9e \xe0 REQ-0012 qui est une nouvelle exigence commerciale critique. Quelles informations critiques MANQUENT dans ce rapport de test qui auraient \xe9t\xe9 utiles aux d\xe9veloppeurs\xa0?","options":["A) R\xe9sultat attendu et r\xe9sultat r\xe9el","B) R\xe9f\xe9rences et statut du d\xe9faut","C) Environnement de test et \xe9l\xe9ment de test","D) Priorit\xe9 et gravit\xe9"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#38, LO : FL-5.5.1). Justification\xa0:\xa0Environnement de test et \xe9l\xe9ment de test","source":"Official Sample Exam A Q#38"},{"id":287,"chapter":6,"topic":"Herramientas de Prueba","question":"Quelle activit\xe9 de test un outil de pr\xe9paration de donn\xe9es prend-il en charge\xa0?","options":["A) Surveillance des tests et contr\xf4le des tests","B) Analyse des tests","C) Conception des tests et mise en \u0153uvre des tests","D) Ach\xe8vement du test"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#39, LO : FL-6.1.1). Justification\xa0: conception des tests et mise en \u0153uvre des tests","source":"Official Sample Exam A Q#39"},{"id":288,"chapter":6,"topic":"Herramientas de Prueba","question":"Quel \xe9l\xe9ment identifie correctement un risque potentiel li\xe9 \xe0 l\u2019automatisation des tests\xa0?","options":["A) Obstacles aux tests","B) Couverture des succursales atteinte","C) Progression des tests","D) Nouveaux risques dans le cycle de test","E) Temps requis pour r\xe9parer un d\xe9faut Question #A26 (1 point) Lequel des \xe9l\xe9ments d\'information suivants contenus dans un rapport d\'avancement de test est le MOINS utile aux repr\xe9sentants d\'affaires ?"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#40, LO : FL-6.2.1). Justification\xa0: Couverture des succursales atteinte","source":"Official Sample Exam A Q#40"},{"id":289,"chapter":1,"topic":"Fundamentos del Testing","question":"Lequel des \xe9nonc\xe9s suivants illustre pourquoi les tests sont n\xe9cessaires\xa0?","options":["A) Les tests dynamiques augmentent la qualit\xe9 en provoquant l\'\xe9chec des objets de test d\'une mani\xe8re que les utilisateurs ne pourraient jamais atteindre","B) Les tests statiques sont utilis\xe9s par les d\xe9veloppeurs pour identifier les bogues dans leur code plus t\xf4t que ne le permettent les tests dynamiques.","C) L\'analyse statique fournit la preuve aux clients que les \xe9l\xe9ments du syst\xe8me qui ne fournissent pas de r\xe9sultats peuvent \xeatre publi\xe9s.","D) Les r\xe9visions augmentent la qualit\xe9 des sp\xe9cifications des exigences et conduisent \xe0 moins de changements n\xe9cessaires dans les produits de travail d\xe9riv\xe9s"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon B, Q#1, LO : FL-1.2.1). Justification\xa0: Les r\xe9visions augmentent la qualit\xe9 des sp\xe9cifications des exigences et conduisent \xe0 moins de changements n\xe9cessaires dans les produits de travail d\xe9riv\xe9s.","source":"Official Sample Exam B Q#1"}]')}}]);